${lines.custrecord_scv_nvl_stt}

${lines.custrecord_scv_nvl_item}

${lines.custrecord_scv_nvl_unit}

${lines.custrecord_scv_nvl_quantity}

${lines.custrecord_scv_nvl_seri}

